function ReconstructRankOneEML(f, x0, y0):
    f00 <- f(x0, y0)            # require f00 > 0
    psi(x) := log( f(x, y0) / f00 )
    phi(y) := log( f(x0, y) )
    return (psi, phi)           # f(x,y) = exp(psi(x) + phi(y))

